import base64
import io
import os
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _read_image_bytes(image_input: Any) -> bytes:
    if isinstance(image_input, bytes):
        return image_input
    if isinstance(image_input, str):
        if image_input.startswith("data:"):
            header, _, payload = image_input.partition(",")
            return base64.b64decode(payload)
        if os.path.isfile(image_input):
            with open(image_input, "rb") as f:
                return f.read()
        return base64.b64decode(image_input)
    if hasattr(image_input, "read"):
        return image_input.read()
    raise TypeError("image_input must be bytes, a file path, a base64 string, or a file-like object")


def _find_label(labels, name: str) -> Optional[Dict[str, Any]]:
    name_lower = name.lower()
    for label in labels:
        if str(label.get("Name", "")).lower() == name_lower:
            return label
    return None


def check_image_safety(
    image_input: Any,
    min_confidence: float = 70.0,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Check an image for unsafe or policy-sensitive visual content using Amazon Rekognition.

    Returns a dictionary with:
      - unsafe: bool
      - risk_labels: list of matched labels with confidence
      - labels: all detected labels
      - text: detected text entries
      - raw: original Rekognition response
    """
    image_bytes = _read_image_bytes(image_input)

    rekognition_kwargs = {}
    if region_name:
        rekognition_kwargs["region_name"] = region_name

    client = boto3.client("rekognition", **rekognition_kwargs)

    try:
        response = client.detect_labels(
            Image={"Bytes": image_bytes},
            MaxLabels=50,
            MinConfidence=min_confidence,
        )
        text_response = client.detect_text(Image={"Bytes": image_bytes})
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Amazon Rekognition request failed: {e}") from e

    labels = response.get("Labels", [])
    detected_text = text_response.get("TextDetections", [])

    risky_label_names = {
        "Explicit Nudity",
        "Nudity",
        "Graphic Violence",
        "Violence",
        "Weapons",
        "Weapon",
        "Blood",
        "Self Harm",
        "Self-Harm",
        "Drugs",
        "Alcohol",
        "Tobacco",
        "Hate Symbols",
        "Gambling",
        "Racy Content",
    }

    risk_labels = []
    for label in labels:
        name = label.get("Name", "")
        if name in risky_label_names or name.lower() in {x.lower() for x in risky_label_names}:
            risk_labels.append(
                {
                    "Name": name,
                    "Confidence": label.get("Confidence"),
                    "Parents": label.get("Parents", []),
                }
            )

    text_strings = []
    for item in detected_text:
        text = item.get("DetectedText")
        if text:
            text_strings.append(
                {
                    "Text": text,
                    "Confidence": item.get("Confidence"),
                    "Type": item.get("Type"),
                }
            )

    unsafe = bool(risk_labels)

    return {
        "unsafe": unsafe,
        "risk_labels": risk_labels,
        "labels": labels,
        "text": text_strings,
        "raw": {
            "detect_labels": response,
            "detect_text": text_response,
        },
    }
